package api

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"testing"

	"example.com/walletsvc/domain"
	"example.com/walletsvc/repo"
	"example.com/walletsvc/service"
)

type idemReplayWallets struct {
	mu             sync.Mutex
	wallets        map[string]domain.Wallet
	inserted       []domain.Transaction
	balanceWrites  int
	failInsert     error
	insertFailures int
}

var _ repo.WalletRepository = (*idemReplayWallets)(nil)

func newIdemReplayWallets() *idemReplayWallets {
	return &idemReplayWallets{wallets: map[string]domain.Wallet{
		"w-1": {ID: "w-1", WalletType: "standard", Balance: 0, Status: domain.StatusEnable},
	}}
}

func (f *idemReplayWallets) GetWallet(_ context.Context, id string) (*domain.Wallet, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	w, ok := f.wallets[id]
	if !ok {
		return nil, fmt.Errorf("no wallet %q", id)
	}
	return &w, nil
}

func (f *idemReplayWallets) UpdateBalance(_ context.Context, id string, balance domain.Balance) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	w := f.wallets[id]
	w.Balance = balance
	f.wallets[id] = w
	f.balanceWrites++
	return nil
}

func (f *idemReplayWallets) UpdateStatus(_ context.Context, id string, status domain.Status) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	w := f.wallets[id]
	w.Status = status
	f.wallets[id] = w
	return nil
}

func (f *idemReplayWallets) InsertTransaction(_ context.Context, t domain.Transaction) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.failInsert != nil {
		f.insertFailures++
		return f.failInsert
	}
	f.inserted = append(f.inserted, t)
	return nil
}

func (f *idemReplayWallets) MaxBalance(context.Context, string) (uint64, error) {
	return 1 << 62, nil
}

func (f *idemReplayWallets) Atomic(ctx context.Context, fn func(context.Context) error) error {
	return fn(ctx)
}

func (f *idemReplayWallets) rowsFor(tracking string) int {
	n := 0
	for _, t := range f.inserted {
		if t.TrackingNumber == tracking {
			n++
		}
	}
	return n
}

type idemReplayCore struct{}

func (idemReplayCore) Settle(context.Context, string) error { return nil }

func idemReplayServer(f *idemReplayWallets) *Server {
	return &Server{Svc: &service.Service{Wallets: f, Core: idemReplayCore{}}}
}

func TestIdemReplay(t *testing.T) {
	ctx := context.Background()

	t.Run("a repeated deposit with the same tracking number credits once", func(t *testing.T) {
		f := newIdemReplayWallets()
		s := idemReplayServer(f)

		first := s.Deposit(ctx, "w-1", 100, "trk-1")
		second := s.Deposit(ctx, "w-1", 100, "trk-1")

		if f.balanceWrites == 0 {
			t.Fatal("the fake repository never saw a balance write — this test proved nothing")
		}
		if fmt.Sprint(first) != fmt.Sprint(second) {
			t.Errorf("the repeat answered %v and the first request %v; a replay must return the first answer", second, first)
		}
		if got := f.wallets["w-1"].Balance; got != 100 {
			t.Errorf("balance after two deliveries of tracking number trk-1 = %d, want 100: the repeat ran the deposit again instead of replaying it", got)
		}
		if n := f.rowsFor("trk-1"); n != 1 {
			t.Errorf("%d history rows carry tracking number trk-1, want 1", n)
		}
	})

	t.Run("a deposit that failed is answered with the same failure, not run again", func(t *testing.T) {
		f := newIdemReplayWallets()
		f.failInsert = errors.New("insert into transactions: connection reset")
		s := idemReplayServer(f)

		first := s.Deposit(ctx, "w-1", 100, "trk-2")
		second := s.Deposit(ctx, "w-1", 100, "trk-2")

		if f.insertFailures == 0 {
			t.Fatal("the injected InsertTransaction failure never fired — this test proved nothing")
		}
		if first == nil {
			t.Fatal("the first attempt reported success although its history write failed")
		}
		if fmt.Sprint(first) != fmt.Sprint(second) {
			t.Errorf("the repeat answered %v and the first request %v; a stored failure must replay as the same failure", second, first)
		}
		if f.balanceWrites != 1 {
			t.Errorf("%d balance writes across a failed deposit and its repeat, want 1: the repeat ran the deposit again", f.balanceWrites)
		}
		if got := f.wallets["w-1"].Balance; got != 0 {
			t.Errorf("both attempts reported failure, yet the balance is %d: the wallet was credited while the caller was told the deposit failed", got)
		}
	})
}

package api

import (
	"context"
	"fmt"
	"runtime"
	"sync"
	"testing"

	"example.com/walletsvc/domain"
	"example.com/walletsvc/repo"
	"example.com/walletsvc/service"
)

type idemConcurrentWallets struct {
	mu                  sync.Mutex
	wallets             map[string]domain.Wallet
	inserted            []domain.Transaction
	balanceWrites       int
	betweenReadAndWrite int
	mostAtOnce          int
}

var _ repo.WalletRepository = (*idemConcurrentWallets)(nil)

func (f *idemConcurrentWallets) GetWallet(_ context.Context, id string) (*domain.Wallet, error) {
	f.mu.Lock()
	w, ok := f.wallets[id]
	f.betweenReadAndWrite++
	if f.betweenReadAndWrite > f.mostAtOnce {
		f.mostAtOnce = f.betweenReadAndWrite
	}
	f.mu.Unlock()
	runtime.Gosched()
	if !ok {
		return nil, fmt.Errorf("no wallet %q", id)
	}
	return &w, nil
}

func (f *idemConcurrentWallets) UpdateBalance(_ context.Context, id string, balance domain.Balance) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	w := f.wallets[id]
	w.Balance = balance
	f.wallets[id] = w
	f.balanceWrites++
	f.betweenReadAndWrite--
	return nil
}

func (f *idemConcurrentWallets) UpdateStatus(_ context.Context, id string, status domain.Status) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	w := f.wallets[id]
	w.Status = status
	f.wallets[id] = w
	return nil
}

func (f *idemConcurrentWallets) InsertTransaction(_ context.Context, t domain.Transaction) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.inserted = append(f.inserted, t)
	return nil
}

func (f *idemConcurrentWallets) MaxBalance(context.Context, string) (uint64, error) {
	return 1 << 62, nil
}

func (f *idemConcurrentWallets) Atomic(ctx context.Context, fn func(context.Context) error) error {
	return fn(ctx)
}

type idemConcurrentCore struct{}

func (idemConcurrentCore) Settle(context.Context, string) error { return nil }

func TestIdemConcurrent(t *testing.T) {
	const n = 32
	ctx := context.Background()
	f := &idemConcurrentWallets{wallets: map[string]domain.Wallet{
		"w-1": {ID: "w-1", WalletType: "standard", Balance: 0, Status: domain.StatusEnable},
	}}
	s := &Server{Svc: &service.Service{Wallets: f, Core: idemConcurrentCore{}}}

	errs := make([]error, n)
	var start, done sync.WaitGroup
	start.Add(1)
	for i := 0; i < n; i++ {
		done.Add(1)
		go func(i int) {
			defer done.Done()
			start.Wait()
			errs[i] = s.Deposit(ctx, "w-1", 100, "trk-1")
		}(i)
	}
	start.Done()
	done.Wait()

	if f.mostAtOnce < 2 {
		t.Fatal("no two deposits were between their balance read and their balance write at the same time — raise n; this run proved nothing")
	}
	succeeded := 0
	for _, err := range errs {
		if err == nil {
			succeeded++
		}
	}
	t.Logf("%d of %d deposits reported success; up to %d were between read and write at once", succeeded, n, f.mostAtOnce)

	rows := 0
	for _, tx := range f.inserted {
		if tx.TrackingNumber == "trk-1" {
			rows++
		}
	}
	if rows != 1 {
		t.Errorf("%d history rows carry tracking number trk-1 after %d simultaneous deliveries, want 1: the key is never checked (service/transfer.go:62)", rows, n)
	}
	if f.balanceWrites != 1 {
		t.Errorf("%d balance writes for one deposit delivered %d times at once, want 1", f.balanceWrites, n)
	}
	if got := f.wallets["w-1"].Balance; got != 100 {
		t.Errorf("balance = %d, want 100: one deposit of 100, delivered %d times at once; the %d history rows say %d was credited, so the balance and its history also disagree", got, n, rows, 100*rows)
	}
}

package api

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"testing"

	"example.com/walletsvc/domain"
	"example.com/walletsvc/repo"
	"example.com/walletsvc/service"
)

type idemCrashAtStepFault struct {
	step    string
	timeout bool
	fired   bool
}

type idemCrashAtStepWallets struct {
	mu            sync.Mutex
	wallets       map[string]domain.Wallet
	inserted      []domain.Transaction
	balanceWrites map[string]int
	settles       int
	calls         map[string]int
	fault         *idemCrashAtStepFault
}

var _ repo.WalletRepository = (*idemCrashAtStepWallets)(nil)
var _ repo.Notifier = (*idemCrashAtStepWallets)(nil)

func newIdemCrashAtStepWallets(fault *idemCrashAtStepFault) *idemCrashAtStepWallets {
	return &idemCrashAtStepWallets{
		wallets: map[string]domain.Wallet{
			"w-a": {ID: "w-a", WalletType: "standard", Balance: 1000, Status: domain.StatusEnable},
			"w-b": {ID: "w-b", WalletType: "standard", Balance: 0, Status: domain.StatusEnable},
		},
		balanceWrites: map[string]int{},
		calls:         map[string]int{},
		fault:         fault,
	}
}

func (f *idemCrashAtStepWallets) newAttempt() {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.calls = map[string]int{}
}

func (f *idemCrashAtStepWallets) at(method string) (failNow, timeout bool) {
	f.calls[method]++
	step := fmt.Sprintf("%s#%d", method, f.calls[method])
	if f.fault != nil && !f.fault.fired && f.fault.step == step {
		f.fault.fired = true
		return true, f.fault.timeout
	}
	return false, false
}

var errIdemCrashAtStepInjected = errors.New("injected failure")

func (f *idemCrashAtStepWallets) GetWallet(_ context.Context, id string) (*domain.Wallet, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if fail, _ := f.at("GetWallet"); fail {
		return nil, errIdemCrashAtStepInjected
	}
	w, ok := f.wallets[id]
	if !ok {
		return nil, fmt.Errorf("no wallet %q", id)
	}
	return &w, nil
}

func (f *idemCrashAtStepWallets) UpdateBalance(_ context.Context, id string, balance domain.Balance) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	fail, timeout := f.at("UpdateBalance")
	if fail && !timeout {
		return errIdemCrashAtStepInjected
	}
	w := f.wallets[id]
	w.Balance = balance
	f.wallets[id] = w
	f.balanceWrites[id]++
	if fail {
		return context.DeadlineExceeded
	}
	return nil
}

func (f *idemCrashAtStepWallets) UpdateStatus(_ context.Context, id string, status domain.Status) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	w := f.wallets[id]
	w.Status = status
	f.wallets[id] = w
	return nil
}

func (f *idemCrashAtStepWallets) InsertTransaction(_ context.Context, t domain.Transaction) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	fail, timeout := f.at("InsertTransaction")
	if fail && !timeout {
		return errIdemCrashAtStepInjected
	}
	f.inserted = append(f.inserted, t)
	if fail {
		return context.DeadlineExceeded
	}
	return nil
}

func (f *idemCrashAtStepWallets) MaxBalance(context.Context, string) (uint64, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if fail, _ := f.at("MaxBalance"); fail {
		return 0, errIdemCrashAtStepInjected
	}
	return 1 << 62, nil
}

func (f *idemCrashAtStepWallets) Atomic(ctx context.Context, fn func(context.Context) error) error {
	return fn(ctx)
}

func (f *idemCrashAtStepWallets) Settle(context.Context, string) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	fail, timeout := f.at("Settle")
	if fail && !timeout {
		return errIdemCrashAtStepInjected
	}
	f.settles++
	if fail {
		return context.DeadlineExceeded
	}
	return nil
}

func TestIdemCrashAtStep(t *testing.T) {
	ctx := context.Background()
	declared := map[domain.Status]bool{
		domain.StatusInitial: true, domain.StatusEnable: true, domain.StatusDisable: true,
		domain.StatusPending: true, domain.StatusDeleted: true,
	}
	transfer := func(s *Server) error {
		return s.Transfer(ctx, domain.TransferInput{FromWalletID: "w-a", ToWalletID: "w-b", Amount: 100})
	}
	deposit := func(s *Server) error {
		return s.Deposit(ctx, "w-a", 100, "trk-1")
	}

	cases := []struct {
		name        string
		run         func(*Server) error
		step        string
		timeout     bool
		wantA       domain.Balance
		wantB       domain.Balance
		wantRows    int
		wantSettles int
	}{
		{"transfer, reading the source fails", transfer, "GetWallet#1", false, 900, 100, 0, 1},
		{"transfer, reading the destination fails", transfer, "GetWallet#2", false, 900, 100, 0, 1},
		{"transfer, the debit fails", transfer, "UpdateBalance#1", false, 900, 100, 0, 1},
		{"transfer, the debit times out after it was applied", transfer, "UpdateBalance#1", true, 900, 100, 0, 1},
		{"transfer, settle fails", transfer, "Settle#1", false, 900, 100, 0, 1},
		{"transfer, settle times out after it was applied", transfer, "Settle#1", true, 900, 100, 0, 1},
		{"transfer, the credit fails", transfer, "UpdateBalance#2", false, 900, 100, 0, 1},
		{"transfer, the credit times out after it was applied", transfer, "UpdateBalance#2", true, 900, 100, 0, 1},
		{"deposit, reading the wallet fails", deposit, "GetWallet#1", false, 1100, 0, 1, 0},
		{"deposit, reading the limit fails", deposit, "MaxBalance#1", false, 1100, 0, 1, 0},
		{"deposit, the credit fails", deposit, "UpdateBalance#1", false, 1100, 0, 1, 0},
		{"deposit, the credit times out after it was applied", deposit, "UpdateBalance#1", true, 1100, 0, 1, 0},
		{"deposit, the history write fails", deposit, "InsertTransaction#1", false, 1100, 0, 1, 0},
		{"deposit, the history write times out after it was applied", deposit, "InsertTransaction#1", true, 1100, 0, 1, 0},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			fault := &idemCrashAtStepFault{step: c.step, timeout: c.timeout}
			f := newIdemCrashAtStepWallets(fault)
			s := &Server{Svc: &service.Service{Wallets: f, Core: f}}

			firstErr := c.run(s)
			if !fault.fired {
				t.Fatalf("the injected failure at %s never fired — this case proved nothing", c.step)
			}
			if firstErr == nil {
				t.Errorf("the attempt that failed at %s reported success", c.step)
			}

			f.newAttempt()
			if err := c.run(s); err != nil {
				t.Fatalf("the retry against healthy dependencies failed: %v", err)
			}

			if got := f.wallets["w-a"].Balance; got != c.wantA {
				t.Errorf("w-a ends at %d after a failure at %s and one retry, want %d, the same as one clean run", got, c.step, c.wantA)
			}
			if got := f.wallets["w-b"].Balance; got != c.wantB {
				t.Errorf("w-b ends at %d after a failure at %s and one retry, want %d, the same as one clean run", got, c.step, c.wantB)
			}
			if got := f.balanceWrites["w-a"]; got != 1 {
				t.Errorf("w-a was written %d times across both attempts, want exactly 1", got)
			}
			if f.settles != c.wantSettles {
				t.Errorf("settle reached the core %d times across both attempts, want %d", f.settles, c.wantSettles)
			}
			if len(f.inserted) != c.wantRows {
				t.Errorf("%d history rows across both attempts, want %d", len(f.inserted), c.wantRows)
			}
			for id, w := range f.wallets {
				if !declared[w.Status] {
					t.Errorf("%s ended in status %q, which domain.Status does not declare", id, w.Status)
				}
			}
		})
	}
}

