type doubleEntrySumsToZeroWallets struct {
	mu      sync.Mutex
	wallets map[string]domain.Wallet
	writes  int
}

var _ repo.WalletRepository = (*doubleEntrySumsToZeroWallets)(nil)

func (f *doubleEntrySumsToZeroWallets) GetWallet(_ context.Context, id string) (*domain.Wallet, error) {
