func (f *doubleEntrySumsToZeroWallets) MaxBalance(context.Context, string) (uint64, error) {
	return 1 << 62, nil
}

func (f *doubleEntrySumsToZeroWallets) Atomic(ctx context.Context, fn func(context.Context) error) error {
	return fn(ctx)
}

func (f *doubleEntrySumsToZeroWallets) total() domain.Balance {
	var sum domain.Balance
	for _, w := range f.wallets {
		sum += w.Balance
	}
	return sum
}

type doubleEntrySumsToZeroCore struct{}

func (doubleEntrySumsToZeroCore) Settle(context.Context, string) error { return nil }

func TestDoubleEntrySumsToZero(t *testing.T) {
	const seed = 20261021
	t.Logf("seed %d", seed)
	r := rand.New(rand.NewSource(seed))
	ctx := context.Background()

	ids := []string{"w-a", "w-b", "w-c"}
	f := &doubleEntrySumsToZeroWallets{wallets: map[string]domain.Wallet{}}
	for _, id := range ids {
		f.wallets[id] = domain.Wallet{ID: id, WalletType: "standard", Balance: 1_000_000, Status: domain.StatusEnable}
	}
	s := &Server{Svc: &service.Service{Wallets: f, Core: doubleEntrySumsToZeroCore{}}}

	accepted := 0
	for i := 0; i < 500; i++ {
		in := domain.TransferInput{
			FromWalletID: ids[r.Intn(len(ids))],
			ToWalletID:   ids[r.Intn(len(ids))],
			Amount:       domain.Amount(1 + r.Intn(5_000)),
		}
		before := f.total()
		if err := s.Transfer(ctx, in); err != nil {
			continue
		}
		accepted++
		if after := f.total(); after != before {
			t.Fatalf("transfer %d (%s -> %s, amount %d) was accepted and moved the total of all wallets from %d to %d: its legs sum to %d, not zero (seed %d)",
				i, in.FromWalletID, in.ToWalletID, in.Amount, before, after, after-before, seed)
		}
	}
	if accepted == 0 || f.writes == 0 {
		t.Fatal("no generated transfer was accepted, so no set of legs was ever checked — this test proved nothing")
	}
}

