type finalStateIsFinalWallets struct {
	mu           sync.Mutex
	wallets      map[string]domain.Wallet
	statusWrites int
}

var _ repo.WalletRepository = (*finalStateIsFinalWallets)(nil)

func (f *finalStateIsFinalWallets) GetWallet(_ context.Context, id string) (*domain.Wallet, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	w, ok := f.wallets[id]
	if !ok {
		return nil, fmt.Errorf("no wallet %q", id)
	}
	return &w, nil
}

func (f *finalStateIsFinalWallets) UpdateBalance(_ context.Context, id string, balance domain.Balance) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	w := f.wallets[id]
	w.Balance = balance
	f.wallets[id] = w
	return nil
}

func (f *finalStateIsFinalWallets) UpdateStatus(_ context.Context, id string, status domain.Status) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	w := f.wallets[id]
	w.Status = status
	f.wallets[id] = w
	f.statusWrites++
	return nil
}

func (f *finalStateIsFinalWallets) InsertTransaction(context.Context, domain.Transaction) error {
	return nil
}

func (f *finalStateIsFinalWallets) MaxBalance(context.Context, string) (uint64, error) {
	return 1 << 62, nil
}

func (f *finalStateIsFinalWallets) Atomic(ctx context.Context, fn func(context.Context) error) error {
	return fn(ctx)
}

type finalStateIsFinalCore struct{}

func (finalStateIsFinalCore) Settle(context.Context, string) error { return nil }

func TestFinalStateIsFinal(t *testing.T) {
	ctx := context.Background()
	f := &finalStateIsFinalWallets{wallets: map[string]domain.Wallet{
		"w-1": {ID: "w-1", WalletType: "standard", Balance: 500, Status: domain.StatusEnable},
	}}
	s := &Server{Svc: &service.Service{Wallets: f, Core: finalStateIsFinalCore{}}}

	if err := s.Delete(ctx, "w-1"); err != nil {
		t.Fatalf("enable -> deleted is a legal move and was refused: %v", err)
	}
	if got := f.wallets["w-1"].Status; got != domain.StatusDeleted {
		t.Fatalf("the wallet is %q after DeleteWallet, so the final state was never reached — this test proved nothing", got)
	}

	before := f.wallets["w-1"]
	writesBefore := f.statusWrites
	err := s.Enable(ctx, "w-1")
	after := f.wallets["w-1"]

	if f.statusWrites == writesBefore && err == nil {
		t.Fatal("EnableWallet neither wrote a status nor refused — the attempt never reached the repository")
	}
	if err == nil {
		t.Errorf("deleted -> enable was accepted: StatusDeleted is final and no exception was declared for it (service/transfer.go:84 sets enable without reading the current status)")
	}
	if after.Status != before.Status {
		t.Errorf("stored status changed from %q to %q on a move that must be refused", before.Status, after.Status)
	}
	if after.Balance != before.Balance {
		t.Errorf("balance changed from %d to %d on a refused move", before.Balance, after.Balance)
	}
	t.Log("deleted -> initial, pending and disable are also refused by the roles, but no function in this module can attempt them")
}

package api

import (
	"context"
	"fmt"
	"sync"
