func TestTransferIsAtomic(t *testing.T) {
	cases := []struct {
		name       string
		failSettle bool
		failCredit bool
	}{
		{"settle fails between the debit and the credit", true, false},
		{"the credit fails after the debit", false, true},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			f := &transferIsAtomicWallets{
				wallets: map[string]domain.Wallet{
					"w-a": {ID: "w-a", WalletType: "standard", Balance: 1000, Status: domain.StatusEnable},
					"w-b": {ID: "w-b", WalletType: "standard", Balance: 0, Status: domain.StatusEnable},
				},
				balanceWrites: map[string]int{},
				failCredit:    c.failCredit,
			}
			core := &transferIsAtomicCore{fail: c.failSettle}
			s := &Server{Svc: &service.Service{Wallets: f, Core: core}}

			err := s.Transfer(context.Background(), domain.TransferInput{FromWalletID: "w-a", ToWalletID: "w-b", Amount: 300})

			if c.failSettle && core.calls == 0 {
				t.Fatal("settle was never called, so the injected failure never fired — this case proved nothing")
			}
			if c.failCredit && !f.creditFailed {
				t.Fatal("the credit was never attempted, so the injected failure never fired — this case proved nothing")
			}
			if err == nil {
				t.Error("the transfer reported success although its second leg failed")
			}
			a, b := f.wallets["w-a"].Balance, f.wallets["w-b"].Balance
			if a+b != 1000 {
				t.Errorf("the two wallets held 1000 together before the transfer and %d after it failed: %d minor units were destroyed", a+b, 1000-(a+b))
			}
			if a != 1000 {
				t.Errorf("w-a holds %d after a failed transfer, want 1000: the debit survived without its credit (service/transfer.go:33)", a)
			}
		})
	}
}

