func TestIllegalTransitionRefused(t *testing.T) {
	ctx := context.Background()
	drivers := map[domain.Status]func(*Server, string) error{
		domain.StatusEnable:  func(s *Server, id string) error { return s.Enable(ctx, id) },
		domain.StatusDeleted: func(s *Server, id string) error { return s.Delete(ctx, id) },
	}

	cases := []struct {
		from, to domain.Status
		legal    bool
	}{
		{domain.StatusDeleted, domain.StatusEnable, false},
		{domain.StatusInitial, domain.StatusEnable, true},
		{domain.StatusInitial, domain.StatusDeleted, true},
		{domain.StatusPending, domain.StatusEnable, true},
		{domain.StatusPending, domain.StatusDeleted, true},
		{domain.StatusDisable, domain.StatusEnable, true},
		{domain.StatusDisable, domain.StatusDeleted, true},
		{domain.StatusEnable, domain.StatusDeleted, true},
	}

	for _, c := range cases {
		t.Run(fmt.Sprintf("%s to %s", c.from, c.to), func(t *testing.T) {
			f := &illegalTransitionRefusedWallets{wallets: map[string]domain.Wallet{
				"w-1": {ID: "w-1", WalletType: "standard", Balance: 500, Status: c.from},
			}}
			s := &Server{Svc: &service.Service{Wallets: f, Core: illegalTransitionRefusedCore{}}}

			err := drivers[c.to](s, "w-1")
			got := f.wallets["w-1"].Status

			if c.legal {
				if err != nil || got != c.to {
					t.Errorf("legal move refused: ended in %q with error %v; a guard that refuses everything is not a guard", got, err)
				}
				return
			}
			if err == nil && f.statusWrites == 0 {
				t.Fatal("the driver neither wrote a status nor refused — the attempt never reached the repository")
			}
			if err == nil {
				t.Errorf("illegal move accepted: nothing checks the current status before writing %q (service/transfer.go:84)", c.to)
			}
			if got != c.from {
				t.Errorf("stored status changed from %q to %q on a move that must be refused", c.from, got)
			}
		})
	}
	t.Log("the other 12 illegal pairs end in initial, pending or disable; no function in this module can attempt them")
}

