func TestCurrencyMixingRefused(t *testing.T) {
	cases := []struct {
		name        string
		value       any
		moneyFields []string
	}{
		{"domain.Wallet", domain.Wallet{}, []string{"Balance"}},
		{"domain.Transaction", domain.Transaction{}, []string{"Amount", "Balance", "Fee"}},
		{"domain.TransferInput", domain.TransferInput{}, []string{"Amount", "Fee"}},
	}

	checked := 0
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			typ := reflect.TypeOf(c.value)
			for _, name := range c.moneyFields {
				if _, ok := typ.FieldByName(name); !ok {
					t.Fatalf("%s has no field %s; the table no longer matches domain/wallet.go", c.name, name)
				}
				checked++
			}
			if _, ok := typ.FieldByName("Currency"); !ok {
				t.Errorf("%s carries money in %v with no currency beside it, so adding EUR minor units to USD minor units compiles and runs without error (domain/wallet.go)", c.name, c.moneyFields)
			}
		})
	}
	if checked == 0 {
		t.Fatal("no money field was examined — this test proved nothing")
	}
	if a, b := domain.Amount(100), domain.Amount(250); a+b != 350 {
		t.Fatalf("same-unit arithmetic is broken: %d + %d = %d", a, b, a+b)
	}
